function encodeBytePayload(g) {
    const a7 = V, i = {
            'BCHnL': function (A, B) {
                return A | B;
            },
            'yLOGf': function (A, B) {
                return A << B;
            }
        }, s = a7(0x225d);
    let t = 'bp_', w = 0x0, x = 0x0;
    for (const A of g) {
        w = i[a7(0x1d2d)](w << 0x8, A), x += 0x8;
        while (x >= 0x6) {
            x -= 0x6, t += s[w >>> x & 0x3f];
        }
    }
    if (x > 0x0)
        t += s[i[a7(0x1049)](w, 0x6 - x) & 0x3f];
    return t;
}
```
